set search_path=public,extensions;
-- Harden all new definer helpers and quote data against direct API execution.
create function public.nexora_submit_review(p_order uuid,p_rating integer,p_body text)returns uuid language plpgsql security definer set search_path=public as $$declare o public.orders;rid uuid;begin select *into o from public.orders where id=p_order and user_id=auth.uid();if not found or o.status<>'delivered' or o.delivered_at<now()-interval '14 days'then raise exception 'Only eligible delivered orders can be reviewed';end if;if exists(select 1 from public.restaurant_reviews where order_id=o.id and edited_until<now())then raise exception 'Review edit window ended';end if;insert into public.restaurant_reviews(user_id,restaurant_id,order_id,rating,body)values(auth.uid(),o.restaurant_id,o.id,p_rating,left(p_body,2000))on conflict(order_id)do update set rating=excluded.rating,body=excluded.body returning id into rid;update public.restaurants set rating_avg=(select round(avg(rating)::numeric,2)from public.restaurant_reviews where restaurant_id=o.restaurant_id and status='visible'),rating_count=(select count(*)from public.restaurant_reviews where restaurant_id=o.restaurant_id and status='visible')where id=o.restaurant_id;return rid;end$$;
create function public.nexora_public_config()returns jsonb language sql stable security definer set search_path=public as $$select coalesce(jsonb_object_agg(key,value),'{}')from public.app_settings where key in('cod.enabled','payments.online_enabled','loyalty.earn_per_paise','loyalty.redeem_paise_per_100_points')$$;
create function public.nexora_set_hours(p_restaurant uuid,p_hours jsonb)returns void language plpgsql security definer set search_path=public as $$declare h jsonb;begin if auth.uid()is null or not(private.nexora_member(p_restaurant)or private.nexora_is_admin())then raise exception 'Access denied';end if;if jsonb_typeof(p_hours)<>'array'or jsonb_array_length(p_hours)>21 then raise exception 'Invalid hours';end if;delete from public.restaurant_hours where restaurant_id=p_restaurant;for h in select value from jsonb_array_elements(p_hours)loop insert into public.restaurant_hours(restaurant_id,weekday,opens,closes,is_closed)values(p_restaurant,(h->>'weekday')::integer,(h->>'opens')::time,(h->>'closes')::time,(h->>'is_closed')::boolean);end loop;end$$;
create function public.nexora_set_zone(p_restaurant uuid,p_lat numeric,p_lng numeric,p_radius integer,p_reason text)returns uuid language plpgsql security definer set search_path=public,extensions as $$declare z uuid;begin if not private.nexora_is_admin()then raise exception 'Admin required';end if;if p_radius not between 100 and 100000 or p_lat not between -90 and 90 or p_lng not between -180 and 180 then raise exception 'Invalid delivery zone';end if;if length(coalesce(p_reason,''))<3 then raise exception 'Reason required';end if;insert into public.restaurant_delivery_zones(restaurant_id,name,center,radius_m)values(p_restaurant,'Delivery area',extensions.ST_SetSRID(extensions.ST_MakePoint(p_lng,p_lat),4326)::extensions.geography,p_radius)returning id into z;insert into public.admin_audit_logs(actor_id,action,entity,entity_id,reason)values(auth.uid(),'set-zone','restaurant_delivery_zones',z::text,p_reason);return z;end$$;
create function public.nexora_admin_role(p_user uuid,p_role text,p_reason text)returns void language plpgsql security definer set search_path=public as $$begin if not private.nexora_is_super_admin()then raise exception 'Super Admin required';end if;if length(coalesce(p_reason,''))<3 then raise exception 'Reason required';end if;insert into public.user_roles(user_id,role)values(p_user,p_role::public.app_role)on conflict do nothing;insert into public.admin_audit_logs(actor_id,action,entity,entity_id,after,reason)values(auth.uid(),'grant-role','user_roles',p_user::text,jsonb_build_object('role',p_role),p_reason);end$$;
create function public.nexora_admin_moderate_review(p_review uuid,p_status text,p_reason text)returns void language plpgsql security definer set search_path=public as $$declare rid uuid;begin if not private.nexora_is_admin()then raise exception 'Admin required';end if;if p_status not in('visible','hidden')or length(coalesce(p_reason,''))<3 then raise exception 'Invalid moderation action';end if;update public.restaurant_reviews set status=p_status where id=p_review returning restaurant_id into rid;update public.restaurants set rating_avg=coalesce((select round(avg(rating)::numeric,2)from public.restaurant_reviews where restaurant_id=rid and status='visible'),0),rating_count=(select count(*)from public.restaurant_reviews where restaurant_id=rid and status='visible')where id=rid;insert into public.admin_audit_logs(actor_id,action,entity,entity_id,reason)values(auth.uid(),'moderate-review','restaurant_reviews',p_review::text,p_reason);end$$;
-- Service-only provider integration. Never grant these to authenticated or anon.
create function public.nexora_attach_gateway(p_order uuid,p_gateway_id text,p_amount bigint)returns void language plpgsql security definer set search_path=public as $$declare o public.orders;begin select *into o from public.orders where id=p_order for update;if not found or o.status<>'pending_payment'or o.total_paise<>p_amount then raise exception 'Order unavailable or amount mismatch';end if;insert into public.payments(order_id,provider,provider_order_id,amount_paise)values(o.id,'razorpay',p_gateway_id,p_amount)on conflict(provider_order_id)do nothing;end$$;
create function public.nexora_mark_paid(p_gateway_id text,p_payment_id text,p_amount bigint,p_event_id text,p_payload jsonb)returns void language plpgsql security definer set search_path=public as $$declare pay public.payments;o public.orders;begin insert into public.webhook_events(provider,event_id,payload)values('razorpay',p_event_id,p_payload)on conflict(provider,event_id)do nothing;if not found then return;end if;select *into pay from public.payments where provider_order_id=p_gateway_id for update;if not found or pay.amount_paise<>p_amount then raise exception 'Payment amount/order mismatch';end if;if pay.status='paid'then update public.webhook_events set processed_at=now(),status='processed'where provider='razorpay'and event_id=p_event_id;return;end if;select *into o from public.orders where id=pay.order_id for update;if o.total_paise<>p_amount then raise exception 'Order amount mismatch';end if;update public.payments set provider_payment_id=p_payment_id,status='paid',signature_verified=true,raw_event_id=p_event_id where id=pay.id;if o.status='pending_payment'then update public.orders set status='placed',payment_status='paid',placed_at=now(),updated_at=now()where id=o.id;insert into public.order_status_history(order_id,from_status,to_status,actor_role,note)values(o.id,'pending_payment','placed','system','Verified Razorpay payment');else if o.status in('cancelled','rejected')then update public.orders set payment_status='refund_pending'where id=o.id;insert into public.refunds(order_id,payment_id,amount_paise,reason)values(o.id,pay.id,p_amount,'Payment captured after cancellation');else raise exception 'Unexpected order status';end if;end if;update public.webhook_events set processed_at=now(),status='processed'where provider='razorpay'and event_id=p_event_id;end$$;
create function public.nexora_record_refund(p_refund uuid,p_provider_id text,p_status text)returns void language plpgsql security definer set search_path=public as $$declare r public.refunds;o public.orders;balance integer;earned integer;begin if p_status not in('processing','succeeded','failed')then raise exception 'Invalid refund state';end if;select *into r from public.refunds where id=p_refund for update;if not found then raise exception 'Refund not found';end if;if r.status='succeeded'then return;end if;update public.refunds set provider_refund_id=p_provider_id,status=p_status::public.refund_status where id=r.id;if p_status='succeeded'then select *into o from public.orders where id=r.order_id for update;update public.orders set payment_status=case when r.amount_paise>=total_paise then 'refunded'::public.payment_status else 'partially_refunded'::public.payment_status end where id=o.id;if r.amount_paise>=o.total_paise then select balance_points into balance from public.loyalty_accounts where user_id=o.user_id for update;earned:=least(balance,o.points_earned);if earned>0 then insert into public.loyalty_ledger(user_id,type,points,order_id,ref,reason)values(o.user_id,'reversal',-earned,o.id,'reverse:'||o.id,'Full refund')on conflict do nothing;end if;end if;end if;end$$;
create function public.nexora_expire_orders()returns integer language plpgsql security definer set search_path=public as $$declare o public.orders;n integer:=0;begin for o in select *from public.orders where(status='pending_payment'and created_at<now()-interval '15 minutes')or(status='placed'and coalesce(placed_at,created_at)<now()-interval '5 minutes')for update skip locked loop update public.orders set status=case when o.status='placed'then 'rejected'::public.order_status else 'cancelled'::public.order_status end,cancelled_at=now(),cancel_reason='Order timed out',payment_status=case when payment_status='paid'then 'refund_pending'::public.payment_status else payment_status end where id=o.id;insert into public.order_status_history(order_id,from_status,to_status,actor_role,note)values(o.id,o.status,case when o.status='placed'then 'rejected'::public.order_status else 'cancelled'::public.order_status end,'system','Timeout');if o.points_redeemed>0 then insert into public.loyalty_ledger(user_id,type,points,order_id,ref,reason)values(o.user_id,'adjustment',o.points_redeemed,o.id,'restore:'||o.id,'Timeout')on conflict do nothing;end if;if o.payment_status='paid'then insert into public.refunds(order_id,payment_id,amount_paise,reason)select o.id,id,o.total_paise,'Order timed out'from public.payments where order_id=o.id and status='paid';end if;update public.coupon_redemptions set released_at=now()where order_id=o.id;n:=n+1;end loop;delete from private.cart_quotes where expires_at<now()-interval '1 day';return n;end$$;
revoke all on function public.nexora_attach_gateway(uuid,text,bigint),public.nexora_mark_paid(text,text,bigint,text,jsonb),public.nexora_record_refund(uuid,text,text),public.nexora_expire_orders()from public,anon,authenticated;
grant execute on function public.nexora_attach_gateway(uuid,text,bigint),public.nexora_mark_paid(text,text,bigint,text,jsonb),public.nexora_record_refund(uuid,text,text),public.nexora_expire_orders()to service_role;
revoke all on function public.nexora_submit_review(uuid,integer,text),public.nexora_set_hours(uuid,jsonb),public.nexora_set_zone(uuid,numeric,numeric,integer,text),public.nexora_admin_role(uuid,text,text),public.nexora_admin_moderate_review(uuid,text,text)from public,anon;
grant execute on function public.nexora_submit_review(uuid,integer,text),public.nexora_set_hours(uuid,jsonb),public.nexora_set_zone(uuid,numeric,numeric,integer,text),public.nexora_admin_role(uuid,text,text),public.nexora_admin_moderate_review(uuid,text,text)to authenticated;
revoke all on function public.nexora_public_config()from public;grant execute on function public.nexora_public_config()to anon,authenticated;
-- Upload policies: public food imagery; avatars are owner-private. No client bucket creation.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('restaurant-media','restaurant-media',true,5242880,array['image/jpeg','image/png','image/webp']),('menu-media','menu-media',true,5242880,array['image/jpeg','image/png','image/webp']),('avatars','avatars',false,5242880,array['image/jpeg','image/png','image/webp'])on conflict(id)do nothing;
create policy nexora_food_images_read on storage.objects for select to anon,authenticated using(bucket_id in('restaurant-media','menu-media'));
create policy nexora_food_images_insert on storage.objects for insert to authenticated with check(bucket_id in('restaurant-media','menu-media')and(private.nexora_member((storage.foldername(name))[1]::uuid)or private.nexora_is_admin()));
create policy nexora_food_images_update on storage.objects for update to authenticated using(bucket_id in('restaurant-media','menu-media')and(private.nexora_member((storage.foldername(name))[1]::uuid)or private.nexora_is_admin()))with check(bucket_id in('restaurant-media','menu-media')and(private.nexora_member((storage.foldername(name))[1]::uuid)or private.nexora_is_admin()));
create policy nexora_food_images_delete on storage.objects for delete to authenticated using(bucket_id in('restaurant-media','menu-media')and(private.nexora_member((storage.foldername(name))[1]::uuid)or private.nexora_is_admin()));
create policy nexora_avatar_read on storage.objects for select to authenticated using(bucket_id='avatars'and(storage.foldername(name))[1]=auth.uid()::text);
create policy nexora_avatar_insert on storage.objects for insert to authenticated with check(bucket_id='avatars'and(storage.foldername(name))[1]=auth.uid()::text);
create policy nexora_avatar_update on storage.objects for update to authenticated using(bucket_id='avatars'and(storage.foldername(name))[1]=auth.uid()::text)with check(bucket_id='avatars'and(storage.foldername(name))[1]=auth.uid()::text);
create policy nexora_avatar_delete on storage.objects for delete to authenticated using(bucket_id='avatars'and(storage.foldername(name))[1]=auth.uid()::text);

create unique index nexora_one_gateway_per_order on public.payments(order_id);
create function public.nexora_admin_record_action(p_entity text,p_id uuid,p_value text,p_reason text)returns void language plpgsql security definer set search_path=public as $$declare points integer;begin if not private.nexora_is_admin()then raise exception 'Admin required';end if;if length(trim(coalesce(p_reason,'')))<3 then raise exception 'Reason required';end if;case p_entity when 'Support'then if p_value not in('pending','resolved','closed')then raise exception 'Invalid ticket status';end if;update public.support_tickets set status=p_value where id=p_id;when 'Settlements'then if p_value not in('approved','paid')then raise exception 'Invalid settlement status';end if;update public.restaurant_settlements set status=p_value,paid_ref=case when p_value='paid'then p_reason else paid_ref end where id=p_id;when 'Deletion requests'then if not private.nexora_is_super_admin()then raise exception 'Super Admin required';end if;if p_value not in('processing','rejected')then raise exception 'Use the retention-aware deletion job to complete requests';end if;update public.deletion_requests set status=p_value,notes=p_reason where id=p_id;when 'Rewards'then points:=p_value::integer;if points=0 or abs(points)>100000 then raise exception 'Invalid adjustment';end if;perform 1 from public.loyalty_accounts where user_id=p_id for update;if not found then raise exception 'Loyalty account not found';end if;insert into public.loyalty_ledger(user_id,type,points,ref,reason,created_by)values(p_id,'adjustment',points,'admin:'||gen_random_uuid(),p_reason,auth.uid());else raise exception 'Unsupported operation';end case;insert into public.admin_audit_logs(actor_id,action,entity,entity_id,after,reason)values(auth.uid(),'update',p_entity,p_id::text,jsonb_build_object('value',p_value),p_reason);end$$;
revoke all on function public.nexora_admin_record_action(text,uuid,text,text)from public,anon;grant execute on function public.nexora_admin_record_action(text,uuid,text,text)to authenticated;
